function QuizFinished({ score, totalScore }) {
  return (
    <div>
      <h2 style={{ textAlign: "center" }}>Congratulations! Quiz Finished!</h2>
      <p
        style={{
          textAlign: "center",
          fontWeight: "bold",
          fontSize: "1.2rem",
          marginTop: "0.5rem",
        }}
      >
        Your final score is: {score} / {totalScore}{" "}
        {score === totalScore ? "🎉" : ""}
      </p>
    </div>
  );
}

export default QuizFinished;
